import{_ as t}from"./chunks/dashboard.Dpem_9-E.js";import{_ as o,o as a,c as s,a3 as r}from"./chunks/framework.Ki30n65y.js";const g=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"admin/dashboard.md","filePath":"admin/dashboard.md"}'),d={name:"admin/dashboard.md"};function n(i,e,h,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The <strong>Dashboard</strong> is the first page Security users see after signing in. It summarizes what the gateway decided over a period of time, so you can spot trends and the packages that are blocked most often.</p><p><img src="'+t+'" alt="The DepGate dashboard"></p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><strong>Requests</strong></td><td>Every package request DepGate evaluated in the period.</td></tr><tr><td><strong>Allowed</strong></td><td>Requests that passed every check, with their share of the total.</td></tr><tr><td><strong>Blocked</strong></td><td>Requests refused by a policy, the malware list or namespace protection.</td></tr><tr><td><strong>Decisions by ecosystem</strong></td><td>Allowed and blocked requests for each ecosystem, as a bar.</td></tr><tr><td><strong>Top blocked</strong></td><td>The packages blocked most often. A package near the top usually means a team depends on something your policies reject: check it with Package check and talk to the team.</td></tr><tr><td><strong>Top allowed</strong></td><td>The packages downloaded most often.</td></tr></tbody></table><p>Use <strong>Time range</strong> to switch between the last 24 hours, 7 days and 30 days, and the refresh button to reload.</p><p>The figures are hourly counts of download decisions. Allowed downloads are counted but not stored one by one; blocks are also kept row by row in the <a href="./decision-ledger">Decision Ledger</a>. New decisions reach the Dashboard within about a minute.</p><p>One request for a package file counts once. Files a client reads alongside the package are not counted when allowed: for Maven only the artifact itself (the <code>.jar</code>, <code>.war</code>, <code>.aar</code> and so on) counts, not its POM, checksums or signatures; for Go only the module <code>.zip</code> counts, not <code>.info</code> or <code>.mod</code>. A refused POM or <code>.info</code> still counts as a block, because the client stops there.</p><h2 id="notices" tabindex="-1">Notices <a class="header-anchor" href="#notices" aria-label="Permalink to &quot;Notices&quot;">​</a></h2><p>When something needs attention, a notice appears at the top of the Dashboard. For example, when a webhook was turned off automatically after repeated failed deliveries, the notice links to <strong>Settings → Webhooks</strong> so you can fix and re-enable it.</p><p>The <strong>Monitoring</strong> item in the sidebar shows a badge with the number of policies in monitor mode. See <a href="./monitoring">Monitor before enforcing</a>.</p>',11)])])}const m=o(d,[["render",n]]);export{g as __pageData,m as default};
